/// Inline SVG icon. Decorative by default (`aria-hidden`); pass `label` when the icon is the
/// only content of a control.
#[component]
pub fn Icon(
    icon: &'static str,
    #[prop(optional)] size: Option<u32>,
    #[prop(optional, into)] class: Option<&'static str>,
    #[prop(optional, into)] label: Option<&'static str>,
) -> impl IntoView {
    let size = size.unwrap_or(18);
    view! {
        <svg
            class=format!("icon {}", class.unwrap_or(""))
            width=size
            height=size
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden=if label.is_some() { None } else { Some("true") }
            aria-label=label
            role=label.map(|_| "img")
            inner_html=icon
        ></svg>
    }
}
